import sys

def min_len_brute(nums, target):
    n = len(nums)
    best = 0
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += nums[j]
            if s >= target:
                if best == 0 or j - i + 1 < best:
                    best = j - i + 1
                break
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[2:2 + n]))
    target = int(data[1])
    print(min_len_brute(nums, target))
